type PaginationMeta = {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
  hasNext: boolean;
  hasPrev: boolean;
};

function buildPaginationMeta(total: number, page: number, limit: number): PaginationMeta {
  const clampedLimit = Math.min(Math.max(limit, 1), 100);
  const totalPages = Math.ceil(total / clampedLimit);
  return {
    page,
    limit: clampedLimit,
    total,
    totalPages,
    hasNext: page < totalPages,
    hasPrev: page > 1,
  };
}

